package agentusage

import (
	"bytes"
	"strings"
	"testing"
)

// fuzzMaxInput keeps one fuzz execution fast. A parent longer than
// MaxLineBytes is not skipped, whether it is a seed or a mutated input (the
// skip only applies between fuzzMaxInput and MaxLineBytes), so the over-long
// line path stays reachable while mutation explores around it.
const fuzzMaxInput = 64 << 10

// FuzzIncrementalMatchesFull: the input is cut into chunks appended one by
// one to a parent and a sub-agent transcript, with one ReadDelta+Apply after
// each; the final aggregate must equal ParseSession on the final files, and
// nothing may panic.
func FuzzIncrementalMatchesFull(f *testing.F) {
	ok := string(msgLine("m1", "claude-f", "end_turn", 1, 2, 3, 4)) + "\n"
	ok2 := string(msgLine("m1", "claude-f", "tool_use", 5, 6, 7, 8)) + "\n"
	// Two models and a 5 min / 1 h cache-write split, one 1 h value above the total.
	split := string(msgLineSplit("m1", "claude-f", "end_turn", 1, 2, 3, 40, 25)) + "\n" +
		string(msgLineSplit("m2", "claude-g", "end_turn", 1, 2, 3, 10, 99)) + "\n" +
		string(msgLineSplit("", "claude-f", "tool_use", 4, 5, 6, 7, 7)) + "\n"
	f.Add([]byte(split), []byte(split[len(split)/3:]), uint8(9))
	f.Add([]byte(split[:len(split)-9]), []byte(split), uint8(0))
	f.Add([]byte(ok+ok2), []byte(ok), uint8(7))
	f.Add([]byte(strings.ReplaceAll(ok+ok2, "\n", "\r\n")), []byte(ok), uint8(1))
	f.Add([]byte(ok[:len(ok)/2]), []byte(ok+ok[:10]), uint8(3))
	f.Add([]byte(`{"message":{"content":"héllo`+"\xe2\x82"), []byte(ok), uint8(2)) // UTF-8 cut mid-rune
	f.Add([]byte(ok+"not json {{{\n\n"+ok2), []byte("[]\n\"x\"\n123\n"), uint8(5))
	f.Add([]byte(ok), []byte(ok2), uint8(0))
	// Timestamped lines with tool_use blocks: streamed repeats, a replaying
	// api-request-blob, a tool result, out-of-order and non-UTC timestamps.
	act := cat(nl(toolLine("m1", 0, "toolu_1", at(10, 5, 0))), nl(toolLine("m1", 0, "toolu_1", at(10, 1, 0))),
		nl(toolLine("m1", 1, "toolu_SENTINEL-DO-NOT-LEAK_1", "2026-10-24T12:04:00+02:00")),
		nl(blobLine("toolu_1")), nl(userLine(at(10, 9, 0))), nl(toolLine("", 0, "", "")))
	f.Add(act, cat(nl(toolLine("s1", 2, "toolu_2", at(10, 3, 0))), nl(blobLine("toolu_2", "toolu_2"))), uint8(0))
	f.Add(act, act, uint8(11))
	f.Add(act[:len(act)/2], act[len(act)/3:], uint8(5))
	f.Add(bytes.Repeat([]byte("a"), MaxLineBytes+10), []byte(ok), uint8(200)) // over-long line

	f.Fuzz(func(t *testing.T, parent, sub []byte, step uint8) {
		if len(parent) > fuzzMaxInput && len(parent) <= MaxLineBytes {
			t.Skip("input too large")
		}
		if len(sub) > fuzzMaxInput {
			t.Skip("input too large")
		}
		s := newSess(t)
		size := int(step)%64 + 1
		if step == 0 {
			size = 0 // line by line
		}
		s.put(s.parent(), nil) // the parent transcript exists before the first read
		a := NewAggregate(s.parent())
		srcs := []*src{{path: s.parent(), data: parent}, {path: s.sub("f1"), data: sub}}
		offs := make([]int, len(srcs))
		readApply(t, a)
		for pending := true; pending; {
			pending = false
			for i, sr := range srcs {
				if offs[i] >= len(sr.data) {
					continue
				}
				pending = true
				end := nextChunk(sr.data, offs[i], size)
				if size > 0 && len(sr.data) > 4096 {
					end = nextChunk(sr.data, offs[i], max(size, len(sr.data)/16))
				}
				s.add(sr.path, sr.data[offs[i]:end])
				offs[i] = end
				readApply(t, a)
			}
		}
		readApply(t, a)
		assertMatchesParse(t, a, s)
	})
}
package agentusage

import "time"

// Agent is the usage of one agent of a session: the orchestrator (Main) or a
// sub-agent.
type Agent struct {
	ID              string
	Main            bool
	Type            string // sub-agent type from its meta file; "" if unknown
	Models          []string
	Tokens          Tokens
	ByModel         []ModelUsage // per-model split of Tokens; the unnamed model last
	Messages        int          // distinct message ids
	PartialMessages int          // messages whose last line has no stop reason
	State           State
	SpawnDepth      int
	ToolCalls       int       // distinct tool_use blocks of the agent's assistant lines
	FirstActivity   time.Time // earliest line timestamp (UTC); zero if none
	LastActivity    time.Time // latest line timestamp (UTC); zero if none
	// key is the table's identity for the agent's lines (the rank of its
	// transcript); empty means ID. finish clears it from its output.
	key string
}

// ModelUsage is the part of an agent's tokens billed to one model, with the
// share of its cache writes that used the 1 h cache. Summed over an agent's
// ByModel it equals Agent.Tokens.
type ModelUsage struct {
	Model        string // "" for messages that name no model
	Tokens       Tokens
	CacheWrite1h int64 // of Tokens.CacheWrite, written with the 1 h cache
}

// CacheWrite5m is the cache writes that used the 5 min cache.
func (m ModelUsage) CacheWrite5m() int64 { return m.Tokens.CacheWrite - m.CacheWrite1h }

// Duration is LastActivity - FirstActivity, or 0 unless both are known.
func (a Agent) Duration() time.Duration {
	if a.FirstActivity.IsZero() || a.LastActivity.IsZero() {
		return 0
	}
	return a.LastActivity.Sub(a.FirstActivity)
}

// PartialOutput reports whether some message of the agent was still being
// written (no stop reason on its last line), so its output count is a floor.
func (a Agent) PartialOutput() bool { return a.PartialMessages > 0 }

// IssueKind classifies a line that could not be counted.
type IssueKind int

const (
	IssueUnreadable IssueKind = iota // not JSON, truncated, or bad counters
	IssueOversized                   // longer than MaxLineBytes
	IssueOpenFailed                  // a sub-agent transcript could not be opened
	IssueReadError                   // reading stopped on an I/O error at Offset
)

// FileIssue locates one skipped line. File is a base name, never a path.
type FileIssue struct {
	File   string
	Offset int64
	Kind   IssueKind
}

// Diagnostics counts what parsing skipped or had to guess.
type Diagnostics struct {
	UnreadableLines     int
	OversizedLines      int
	NoUsage             int
	NoMessageID         int
	CrossFileDuplicates int
	MetaMissing         int
	MetaUnreadable      int
	TruncatedFiles      []string
	Files               []FileIssue
}

// Degraded reports whether anything was skipped or guessed.
func (d Diagnostics) Degraded() bool {
	return d.UnreadableLines > 0 || d.OversizedLines > 0 || d.NoUsage > 0 ||
		d.NoMessageID > 0 || d.CrossFileDuplicates > 0 || d.MetaMissing > 0 ||
		d.MetaUnreadable > 0 || len(d.TruncatedFiles) > 0 || len(d.Files) > 0
}

// Usage is the parsed usage of one session.
type Usage struct {
	SessionID   string
	Agents      []Agent
	Versions    []string
	Diagnostics Diagnostics
}

// Total returns the tokens of every agent.
func (u Usage) Total() Tokens {
	var t Tokens
	for _, a := range u.Agents {
		t = t.Add(a.Tokens)
	}
	return t
}
