	parts = append(parts, `"totalDuration":123,"totalLinesAdded":4,`+
		`"modelUsage":{"claude-haiku-4-5-20251001":{"inputTokens":9,"costUSD":0.5}}`)
	return []byte("{" + strings.Join(parts, ",") + "}\n")
}

