			if got.Total() != base.Total() || got.Agents[0].Messages != base.Agents[0].Messages {
				t.Errorf("counts moved: %+v/%d -> %+v/%d", base.Total(), base.Agents[0].Messages, got.Total(), got.Agents[0].Messages)
			}
